-- Postgres version of the live D1 schema (worker-api/schema/migrations/000-004, mirrored in
-- database/init.sql). Column names, nullability and meanings are unchanged so the Phase 3
-- data copy is a straight insert:
--   * ids are `generated by default as identity`, so existing D1 ids can be inserted as-is
--   * 0/1 flags stay integer, and dates/times stay text
--   * timestamp defaults produce the same 'YYYY-MM-DD HH:MM:SS' (UTC) text D1 stores
--   * COLLATE NOCASE uniqueness becomes a unique index on lower(...)
-- RLS is on for every table with no policies: only the server (postgres role) reads or
-- writes, and the public anon key sees nothing.

create or replace function clawholics_utc_now() returns text
language sql stable
as $$ select to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI:SS') $$;

-- CMS ---------------------------------------------------------------------------------------

create table content (
  id integer generated by default as identity primary key,
  key text unique,
  value text
);

create table home_carousel (
  id integer generated by default as identity primary key,
  image_url text not null,
  position integer not null
);

create table faqs (
  id integer generated by default as identity primary key,
  question text,
  answer text,
  display_order integer not null
);

create table terms_and_conditions (
  id integer generated by default as identity primary key,
  section text not null,
  content text not null,
  display_order integer not null
);

-- CATALOG -----------------------------------------------------------------------------------

create table service_categories (
  id integer generated by default as identity primary key,
  name text not null,
  slug text not null unique,
  description text,
  image text,
  position integer not null default 0,
  is_active integer not null default 1,
  created_at text default clawholics_utc_now()
);
-- D1: name TEXT NOT NULL UNIQUE COLLATE NOCASE
create unique index service_categories_name_nocase on service_categories (lower(name));

create table services (
  id integer generated by default as identity primary key,
  name text,
  category text,
  description text,
  master_price integer not null,
  junior_price integer not null,
  duration text,
  image text,
  category_id integer references service_categories (id),
  is_active integer not null default 1,
  position integer not null default 0,
  pricing_mode text not null default 'tiered' check (pricing_mode in ('tiered', 'single'))
);
create index idx_services_category on services (category_id);

create table service_gallery (
  id integer generated by default as identity primary key,
  service_id integer not null references services (id) on delete cascade,
  image_url text not null,
  position integer not null
);
create unique index idx_unique_service_gallery_item on service_gallery (service_id, image_url, position);

-- ARTISTS -----------------------------------------------------------------------------------

create table nailist_categories (
  id integer generated by default as identity primary key,
  name text not null unique
);

create table nailists (
  id integer generated by default as identity primary key,
  name text not null,
  category_id integer not null default 2 references nailist_categories (id),
  specialty text,
  bio text,
  image text
);

create table nailist_services (
  nailist_id integer not null references nailists (id) on delete cascade,
  service_id integer not null references services (id) on delete cascade,
  primary key (nailist_id, service_id)
);

create table nailist_day_offs (
  id integer generated by default as identity primary key,
  nailist_id integer not null references nailists (id) on delete cascade,
  day_off_type text not null check (day_off_type in ('REGULAR', 'CUSTOM')),
  day_of_week integer check (day_of_week between 0 and 6),
  date text,
  created_at text default clawholics_utc_now(),
  check (
    (day_off_type = 'REGULAR' and day_of_week is not null and date is null)
    or (day_off_type = 'CUSTOM' and day_of_week is null and date is not null)
  )
);
create unique index idx_nailist_regular_day_off on nailist_day_offs (nailist_id, day_of_week)
  where day_off_type = 'REGULAR';
create unique index idx_nailist_custom_day_off on nailist_day_offs (nailist_id, date)
  where day_off_type = 'CUSTOM';

create table nailist_time_slots (
  id integer generated by default as identity primary key,
  nailist_id integer not null,
  start_time text not null,
  end_time text not null
);
create unique index idx_unique_nailist_time_slot on nailist_time_slots (nailist_id, start_time, end_time);

-- USERS -------------------------------------------------------------------------------------

create table users (
  id integer generated by default as identity primary key,
  clerk_id text unique not null,
  email text unique not null,
  role text default 'customer',
  created_at text default clawholics_utc_now()
);

create table customer_profiles (
  user_id integer primary key references users (id) on delete cascade,
  first_name text not null,
  last_name text not null,
  phone text,
  dob text,
  gender text,
  stamps integer default 0,
  alt_phone text,
  preferred_contact_method text,
  facebook_handle text,
  instagram_handle text
);

create table admin_profiles (
  user_id integer primary key references users (id) on delete cascade,
  first_name text not null,
  last_name text not null,
  employee_id text,
  department text
);

create table scan_history (
  id integer generated by default as identity primary key,
  admin_clerk_id text not null,
  client_clerk_id text not null,
  action text not null,
  created_at text default clawholics_utc_now()
);

-- BOOKING AND PAYMENTS ----------------------------------------------------------------------

create table appointments (
  id integer generated by default as identity primary key,
  user_id integer not null references users (id),
  service_id integer not null,
  service_name text not null,
  nailist_id integer not null,
  nailist_name text not null,
  appointment_date text not null,
  appointment_time text not null,
  status text default 'PENDING',
  created_at text default clawholics_utc_now(),
  expires_at text,
  walkin_first_name text,
  walkin_last_name text,
  walkin_phone text,
  walkin_email text
);
-- One active booking per artist and slot (D1 relied on its single writer; here it also
-- guards concurrent bookings).
create unique index idx_unique_active_slot on appointments (nailist_id, appointment_date, appointment_time)
  where lower(trim(status)) not in ('cancelled', 'canceled', 'refunded');

create table payments (
  id text primary key,
  appointment_id integer not null references appointments (id),
  amount integer not null,
  status text not null,
  payment_method text not null,
  external_id text unique not null,
  invoice_url text,
  created_at text default clawholics_utc_now()
);
create index idx_payment_appointment on payments (appointment_id);

create table site_settings (
  key text primary key,
  value text not null,
  updated_at text default clawholics_utc_now()
);

create table payment_proofs (
  id integer generated by default as identity primary key,
  appointment_id integer not null references appointments (id),
  user_id integer not null references users (id),
  image_url text not null,
  status text not null default 'PENDING' check (status in ('PENDING', 'APPROVED', 'REJECTED')),
  admin_note text,
  reviewed_by integer references users (id),
  created_at text default clawholics_utc_now(),
  updated_at text default clawholics_utc_now()
);
create index idx_payment_proofs_appointment on payment_proofs (appointment_id);
create index idx_payment_proofs_status on payment_proofs (status);

-- Reference rows the app depends on ------------------------------------------------------

-- nailists.category_id defaults to 2 (Junior Technician)
insert into nailist_categories (id, name) values (1, 'Master Technician'), (2, 'Junior Technician')
  on conflict (id) do nothing;
select setval(pg_get_serial_sequence('nailist_categories', 'id'), (select max(id) from nailist_categories));

-- Same rows D1 migration 004 inserts
insert into site_settings (key, value) values
  ('downpayment_amount', '500'),
  ('payment_methods', '["GCASH"]')
  on conflict (key) do nothing;

-- RLS: server-only access ------------------------------------------------------------------

alter table content enable row level security;
alter table home_carousel enable row level security;
alter table faqs enable row level security;
alter table terms_and_conditions enable row level security;
alter table service_categories enable row level security;
alter table services enable row level security;
alter table service_gallery enable row level security;
alter table nailist_categories enable row level security;
alter table nailists enable row level security;
alter table nailist_services enable row level security;
alter table nailist_day_offs enable row level security;
alter table nailist_time_slots enable row level security;
alter table users enable row level security;
alter table customer_profiles enable row level security;
alter table admin_profiles enable row level security;
alter table scan_history enable row level security;
alter table appointments enable row level security;
alter table payments enable row level security;
alter table site_settings enable row level security;
alter table payment_proofs enable row level security;
